 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each pair of same-row outline endpoints fills the interval between them.
    # Nested/overlapping intervals encode the triangular filled region.
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value != 0]
        if len(cols) >= 2:
            for c in range(cols[0] + 1, cols[-1]):
                out[r][c] = 2
    # Fill portions between the two diagonal boundary lines: infer the sloping
    # sides by connecting outline points in adjacent rows, then fill between them.
    pts = [[c for c, v in enumerate(row) if v != 0] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            # Fill only where a boundary point exists on both sides in this row
            # or in a lower row (the triangular interior).
            left = any(pts[rr] and min(pts[rr]) < c for rr in range(r, h))
            right = any(pts[rr] and max(pts[rr]) > c for rr in range(r, h))
            if left and right:
                out[r][c] = 2
    return out
